'use strict';
const products=[
{id:0,name:'Top Impulso',type:'Top',color:'Oliva',price:129,desc:'Top de alças nadador, com decote arredondado e elástico na base. Uma silhueta limpa para combinar com seus essenciais.',material:'Poliamida e elastano',tag:'ESSENCIAL'},
{id:1,name:'Legging Ritmo',type:'Legging',color:'Oliva',price:219,desc:'Legging de cintura alta e comprimento até o tornozelo. O cós largo e a modelagem ajustada acompanham suas combinações.',material:'Poliamida e elastano',tag:'CINTURA ALTA'},
{id:2,name:'Short Fluxo',type:'Short',color:'Preto',price:159,desc:'Short biker de cintura alta e comprimento intermediário. Uma alternativa versátil para dias de treino e movimento.',material:'Poliamida e elastano',tag:'BIKER'},
{id:3,name:'Jaqueta Aurora',type:'Jaqueta',color:'Off-white',price:289,desc:'Jaqueta cropped com zíper frontal. Uma camada leve para completar o look entre um compromisso e outro.',material:'Poliéster e elastano',tag:'TERCEIRA PEÇA'},
{id:4,name:'Regata Pulso',type:'Regata',color:'Preto',price:119,desc:'Regata sem mangas com modelagem ajustada e gola redonda. Um essencial simples, fácil de usar e combinar.',material:'Poliamida e elastano',tag:'ESSENCIAL'},
{id:5,name:'Casaco Equilíbrio',type:'Casaco',color:'Oliva',price:269,desc:'Casaco leve de mangas longas e comprimento cropped. Uma camada extra para acompanhar o seu ritmo.',material:'Poliéster e elastano',tag:'CAMADA LEVE'}
];
const sizes=['P','M','G','GG'];const money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});const $=id=>document.getElementById(id);const position=id=>`${(id%3)*50}% ${Math.floor(id/3)*100}%`;const photo=(p,extra='')=>`<div class="photo" role="img" aria-label="${p.name} ${p.color}" style="background-position:${position(p.id)}">${extra}</div>`;
let cart=[];try{const saved=JSON.parse(localStorage.getItem('vlana-cart')||'[]');if(Array.isArray(saved))cart=saved.filter(i=>Number.isInteger(i.id)&&products[i.id]&&sizes.includes(i.size)&&Number.isInteger(i.qty)&&i.qty>0&&i.qty<100);}catch{cart=[];}
let selected=[0,1,3],lookSizes=['M','M','M'];let toastTimer;
$('products').innerHTML=products.map(p=>`<button class="product-card" data-product="${p.id}" aria-label="Ver detalhes de ${p.name}">${photo(p,`<span class="tag">${p.tag}</span><span class="view">Ver peça</span>`)}<div class="product-meta"><h3>${p.name}</h3><span>${money(p.price)}</span></div><p>${p.type} · ${p.color}</p></button>`).join('');
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),2800);}
function save(){try{localStorage.setItem('vlana-cart',JSON.stringify(cart));}catch{}$('count').textContent=cart.reduce((a,i)=>a+i.qty,0);}
function add(id,size){const row=cart.find(i=>i.id===id&&i.size===size);if(row)row.qty=Math.min(row.qty+1,99);else cart.push({id,size,qty:1});save();}
function openProduct(id){const p=products[id];$('product-detail').innerHTML=`<div class="detail-layout">${photo(p)}<div class="detail-copy"><p class="eyebrow">V’LANA / ${p.type.toUpperCase()}</p><h2>${p.name}</h2><p class="price">${money(p.price)}</p><p>${p.desc}</p><p>Cor: ${p.color}<br>Composição: ${p.material}</p><label for="product-size">Tamanho<select id="product-size">${sizes.map(s=>`<option>${s}</option>`).join('')}</select></label><button class="primary" id="add-product">Adicionar à sacola</button><p class="small">Peça ilustrativa da coleção conceito. Valores e composição demonstrativos.</p></div></div>`;$('add-product').onclick=()=>{add(id,$('product-size').value);$('product-dialog').close();toast(`${p.name} adicionada à sacola`);};$('product-dialog').showModal();}
function renderBuilder(){const groups=[[0,4],[1,2],[3,5]];const labels=['Comece pelo top','Escolha a base','Complete com uma camada'];$('builder-controls').innerHTML=groups.map((ids,k)=>`<div class="step"><h3><span>0${k+1}</span>${labels[k]}</h3><div class="choices">${ids.map(id=>`<button class="choice" data-step="${k}" data-choice="${id}" aria-pressed="${selected[k]===id}">${products[id].name}</button>`).join('')}${k===2?`<button class="choice" data-step="2" data-choice="-1" aria-pressed="${selected[2]===-1}">Sem camada</button>`:''}</div>${selected[k]>=0?`<label class="size-row" for="look-size-${k}">Tamanho<select id="look-size-${k}" data-size-step="${k}">${sizes.map(s=>`<option ${lookSizes[k]===s?'selected':''}>${s}</option>`).join('')}</select></label>`:''}</div>`).join('');renderLook();}
function renderLook(){const active=selected.filter(id=>id>=0).map(id=>products[id]);$('look-grid').innerHTML=active.map(p=>`<div>${photo(p)}<p>${p.name}<br>${p.color}</p></div>`).join('');$('look-name').textContent=selected[1]===2?'Seu ritmo, com leveza.':'Seu movimento, por inteiro.';$('look-summary').textContent=active.map(p=>p.name).join(' + ');$('look-price').textContent=money(active.reduce((a,p)=>a+p.price,0));document.querySelector('.look-glow').style.background=selected[1]===2?'radial-gradient(ellipse at 50% 20%,#c5d9a51a,transparent 65%)':'radial-gradient(ellipse at 50% 20%,#a7c37835,transparent 65%)';}
function renderCart(){const total=cart.reduce((a,i)=>a+products[i.id].price*i.qty,0);$('cart-items').innerHTML=cart.length?cart.map((i,k)=>{const p=products[i.id];return `<div class="cart-item">${photo(p)}<div><h3>${p.name}</h3><p>${p.color} · Tamanho ${i.size}</p><p>${money(p.price*i.qty)}</p><div class="quantity"><button data-qty="${k}" data-delta="-1" aria-label="Diminuir quantidade de ${p.name}">−</button><span aria-label="Quantidade">${i.qty}</span><button data-qty="${k}" data-delta="1" aria-label="Aumentar quantidade de ${p.name}">+</button><button class="remove" data-remove="${k}" aria-label="Remover ${p.name}">Remover</button></div></div></div>`;}).join(''):'<div class="empty">Sua sacola ainda está vazia.<br>Encontre peças para o seu movimento.<br><br><button class="primary" id="continue-shopping">Explorar coleção</button></div>';$('cart-bottom').innerHTML=cart.length?`<div class="total"><span>Subtotal</span><strong>${money(total)}</strong></div><p class="cart-note">Esta é uma loja conceito. A sacola permite experimentar suas combinações; não há pagamento ou compra real.</p><button class="primary" id="continue-shopping">Continuar explorando</button>`:'';}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.product!==undefined)openProduct(Number(b.dataset.product));if(b.dataset.close)$(b.dataset.close).close();if(b.dataset.choice!==undefined){selected[Number(b.dataset.step)]=Number(b.dataset.choice);renderBuilder();}if(b.dataset.qty!==undefined){const k=Number(b.dataset.qty);cart[k].qty=Math.min(99,cart[k].qty+Number(b.dataset.delta));if(cart[k].qty<=0)cart.splice(k,1);save();renderCart();}if(b.dataset.remove!==undefined){cart.splice(Number(b.dataset.remove),1);save();renderCart();}if(b.id==='continue-shopping'){$('cart-dialog').close();document.getElementById('colecao').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}});
document.addEventListener('change',e=>{if(e.target.dataset.sizeStep!==undefined)lookSizes[Number(e.target.dataset.sizeStep)]=e.target.value;});
$('open-cart').onclick=()=>{renderCart();$('cart-dialog').showModal();};$('add-look').onclick=()=>{selected.forEach((id,k)=>{if(id>=0)add(id,lookSizes[k]);});toast('Seu look foi adicionado à sacola');};for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});renderBuilder();save();
